sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    var transactionType = current.getValue('transaction_type')
    var sign = calc.signFor(transactionType)
    if (sign >= 0) {
        // Only outbound movements (production_issue, dispatch) can drive a
        // balance negative.
        return
    }

    var itemType = current.getValue('item_type')
    var itemField = calc.ITEM_FIELD['' + itemType]
    if (!itemField) {
        return
    }

    var itemId = current.getValue(itemField)
    if (!itemId) {
        return
    }

    // Exclude THIS row from the ledger sum. Without the exclusion, editing an
    // existing issue/dispatch row would count its own previous contribution a
    // second time and reject valid edits.
    var others = calc.ledgerBalance(itemType, itemId, current.getUniqueValue())
    var quantity = calc.toNum(current.getValue('quantity'))
    var resulting = others + sign * quantity

    if (resulting < -0.000001) {
        var itemName = calc.itemMeta(itemType, itemId).item_name || itemId
        gs.addErrorMessage(
            'Insufficient stock for ' +
                itemName +
                ': available ' +
                others +
                ', requested ' +
                quantity +
                '. Resulting balance would be ' +
                resulting +
                '.',
        )
        current.setAbortAction(true)
    }
})(current, previous)
